// Some portions generated by Co-Pilot
import { render, screen, fireEvent, act } from "@testing-library/react";
import { describe, it, expect, vi } from "vitest";
import { axe } from "vitest-axe";
import Testimonials from "../index";
import testimonialData from "@/data/testimonials.json";

describe("Testimonials", () => {
  it("renders the full first member quote without rewriting it", () => {
    render(<Testimonials type="member" />);
    const first = testimonialData.find((item) => item.type === "member")!;
    expect(screen.getByText(first.quote, { exact: false })).toBeVisible();
    expect(screen.getByText(first.name)).toBeVisible();
    expect(screen.getByText(first.role)).toBeVisible();
  });

  it("provides a single company selector for each member", () => {
    render(<Testimonials type="member" />);
    expect(screen.getAllByRole("button")).toHaveLength(3);
    expect(screen.getByRole("button", { name: "Microsoft" })).toHaveAttribute(
      "aria-pressed",
      "true",
    );
    expect(
      screen.getByRole("button", { name: "Alibaba Cloud" }),
    ).toHaveAttribute("aria-pressed", "false");
  });

  it("updates the quote, author and selected company together", () => {
    render(<Testimonials type="member" />);
    const button = screen.getByRole("button", { name: "Red Hat" });
    expect(button.querySelector("img")).toHaveAttribute(
      "src",
      "/images/adopters/Logo-RedHat-A-White-RGB.svg",
    );
    fireEvent.click(button);
    const selected = testimonialData.find(
      (item) => item.companyName === "Red Hat",
    )!;
    expect(screen.getByText(selected.quote, { exact: false })).toBeVisible();
    expect(screen.getByText(selected.name)).toBeVisible();
    expect(button).toHaveAttribute("aria-pressed", "true");
    expect(screen.getByRole("button", { name: "Microsoft" })).toHaveAttribute(
      "aria-pressed",
      "false",
    );
  });

  it("does not interrupt reading with automatic rotation", () => {
    vi.useFakeTimers();
    try {
      render(<Testimonials type="member" />);
      fireEvent.click(screen.getByRole("button", { name: "Alibaba Cloud" }));
      act(() => vi.advanceTimersByTime(60000));
      expect(screen.getByText("Sanhong Li")).toBeVisible();
    } finally {
      vi.useRealTimers();
    }
  });

  it("resets the selection when switching between member and sustainer quotes", () => {
    const { rerender } = render(<Testimonials type="member" />);
    fireEvent.click(screen.getByRole("button", { name: "Red Hat" }));
    rerender(<Testimonials type="sustainer" />);
    expect(screen.getByText("Laurent Almeras")).toBeVisible();
    expect(
      screen.queryByRole("button", { name: "Red Hat" }),
    ).not.toBeInTheDocument();
    rerender(<Testimonials type="member" />);
    expect(screen.getByText("Martijn Verburg")).toBeVisible();
  });

  it("keeps the complete longer sustainer quote available", () => {
    render(<Testimonials type="sustainer" />);
    const first = testimonialData.find((item) => item.type === "sustainer")!;
    expect(screen.getByText(first.quote, { exact: false })).toBeVisible();
  });

  it("announces user-triggered quote changes and has no accessibility violations", async () => {
    const { container } = render(<Testimonials type="member" />);
    const button = screen.getByRole("button", { name: "Microsoft" });
    const quoteId = button.getAttribute("aria-controls");
    const figure = container.querySelector("figure");
    expect(figure).toHaveAttribute("id", quoteId);
    expect(figure).toHaveAttribute("aria-live", "polite");
    expect(await axe(container)).toHaveNoViolations();
  });
});
